L9_1.m_CharStrID = "MINATO_NANA_NULL_NULL"
L9_1.m_Pos = "L"
L9_1.m_Talk_KOREA = "장로는 어디로 사라졌지? 폭격에 휩쓸린 건가?"
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "長老はどこに消えたんだ？　爆撃に巻き込まれた？"
L9_1.m_Talk_ENG = "Where is the elder? Maybe she was bombarded?"
L9_1.m_Talk_TWN = "長老人呢？是捲入爆炸裡嗎？"
L9_1.m_Talk_THA = "ผู้อาวุโสไปไหนแล้วล่ะ? หรือโดนถล่มไปแล้ว?"
