L12_1.m_Pos = "R"
L12_1.m_Talk_KOREA = "마사키님이 침식체들을 저지하는 동안, 어서 움직여요!"
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "雅紀様が侵食体を足止めしている間に急ぎましょう！"
L12_1.m_Talk_ENG = "We have to go while Mr. Katori is holding the C.O.s back!"
L12_1.m_Talk_TWN = "趁雅紀對抗侵蝕體的時候，趕快動作！"
L12_1.m_Talk_THA = "เราต้องไปกันตอนที่นายท่านมาซากิช่วยถ่วงพวกวัตถุคอร์รัปต์ไว้นี่แหละค่ะ!"
L12_1.m_Talk_VTN = "Chúng ta phải đi trong khi Cậu Masaki đang giữ chân V.T.A.M.!"
L12_1.m_Talk_SCN = "在雅纪阻挡侵蚀体们的时候，去祭坛那里！"
L12_1.m_Talk_DEU = "Wir müssen gehen, während Masaki die C.O.s zurückhält!"
L12_1.m_Talk_FRA = "Allons-y pendant que Katori retient les Objets Corrompus !"
