L20_1 = {}
L20_1.m_CutScenKey_Talk = "NANAHARA_ACT4_INTERLUDE1@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 3600403
L20_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_DESPAIR"
L20_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L20_1.m_Pos = "R"
L20_1.m_Talk_KOREA = "이번 계획은 저희 둘만 알아야 하는 것이라고 말씀드렸을 텐데요."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "今回の計画は私たち二人だけの秘密だと申し上げたと思いますが。"
L20_1.m_Talk_ENG = "I told you not to talk about this plan to anyone else."
L20_1.m_Talk_TWN = "我不是說過，這次的計劃只有我們兩個人知道。"
L20_1.m_Talk_THA = "ฉันบอกคุณว่าอย่าบอกแผนการนี้กับใครไงคะ"
L20_1.m_Talk_VTN = "Tôi đã bảo cậu không được nói về kế hoạch này với bất kỳ ai khác."
L20_1.m_Talk_SCN = "这次的计划，我说过只能我们两个人知道吧。"
L20_1.m_Talk_DEU = "Ich habe doch gesagt, dass dieser Plan geheim ist!"
L20_1.m_Talk_FRA = "Je vous avais demandé de ne parler du plan à personne, vous vous souvenez ?"
L21_1 = {}
L21_1.m_CutScenKey_Talk = "NANAHARA_ACT4_INTERLUDE1@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 3600403
