L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "あはは……そうだったね。ごめん……"
L21_1.m_Talk_ENG = "Hah hah, you did... Sorry..."
L21_1.m_Talk_TWN = "哈哈……你是說過，抱歉……"
L21_1.m_Talk_THA = "ฮ่าฮ่า จริงด้วย... ขอโทษนะ..."
