L23_1 = {}
L23_1.m_CutScenKey_Talk = "NANAHARA_ACT4_INTERLUDE1@23#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 3600403
L23_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L23_1.m_Pos = "R"
L23_1.m_Talk_KOREA = "마사키님을 휘말리게 하고 싶지 않았지만, 결국 이렇게 도움을 받았군요."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "雅紀様を巻き込みたくなかったのですが、\n結局こうして助けていただきました。"
L23_1.m_Talk_ENG = "I didn’t want to bother Mr. Katori, but he’s here to help me anyways."
L23_1.m_Talk_TWN = "我不想讓雅紀捲入其中，但還是得到他的幫助。"
L23_1.m_Talk_THA = "ฉันไม่อยากรบกวนนายท่านมาซากิ แต่เขาก็ยังมาช่วยฉันอยู่ดี"
L23_1.m_Talk_VTN = "Tôi đã không muốn làm phiền Chủ Nhân Masaki, nhưng dù sao thì cậu ấy cũng ở đây để giúp tôi."
L23_1.m_Talk_SCN = "虽然不想让雅纪也卷入这件事，但最终他却帮了大忙。"
L23_1.m_Talk_DEU = "Ich wollte ihn eigentlich nicht stören, aber jetzt wo er eh zur Hilfe hergeeilt ist ..."
L23_1.m_Talk_FRA = "Je ne voulais pas impliquer Katori dans cette histoire, mais il a fini par en faire partie malgré lui."
L24_1 = {}
