L24_1.m_CutScenID = 3600403
L24_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_LAUGH"
L24_1.m_CharStrID = "MINATO_NANA_NULL_NULL"
L24_1.m_Pos = "L"
L24_1.m_Talk_KOREA = "도와주러 올 거라곤 믿고 있었지만…… 의외였어."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "助けに来るとは信じていたけど……意外だったよ。"
L24_1.m_Talk_ENG = "I knew he was coming to help me... but it was beyond my expectations."
L24_1.m_Talk_TWN = "雖然我相信他會來幫我…不過還是很意外。"
L24_1.m_Talk_THA = "ผมรู้แหละว่าเขาจะมาช่วย... แต่ก็มาแบบเหนือความคาดหมายไปอีก"
L24_1.m_Talk_VTN = "Tôi biết cậu ấy đến để giúp tôi... nhưng điều đó nằm ngoài dự đoán của tôi."
L24_1.m_Talk_SCN = "不过他能够来，确实很让我意外。"
L24_1.m_Talk_DEU = "Ich wusste, dass er kommen würde, um mir zu helfen ... Aber er hat schon jetzt viel mehr getan, als ich mir hätte wünschen können."
L24_1.m_Talk_FRA = "Je savais qu'il viendrait m'aider, mais... là, il a déjoué tous mes pronostics."
L25_1 = {}
L25_1.m_CutScenKey_Talk = "NANAHARA_ACT4_INTERLUDE1@25#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 3600403
L25_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "MINATO_NANA_NULL_NULL"
L25_1.m_Pos = "L"
L25_1.m_Talk_KOREA = "마사키가 저런 함선도 몰 줄 알았다니."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "雅紀がまさか艦船も操縦できたなんて。"
L25_1.m_Talk_ENG = "I didn’t know he could drive such a big ship."
L25_1.m_Talk_TWN = "雅紀居然會開種艦船。"
L25_1.m_Talk_THA = "ไม่รู้ว่าเขาขับยานลำใหญ่ขนาดนั้นได้ด้วย"
L25_1.m_Talk_VTN = "Tôi không biết cậu ấy có thể lái một con tàu lớn như vậy."
L25_1.m_Talk_SCN = "雅纪竟然会开那种舰船。"
L25_1.m_Talk_DEU = "Wer hätte gewusst, dass Masaki ein so großes Schiff fahren kann."
L25_1.m_Talk_FRA = "Qui aurait pu penser qu'il pouvait piloter un tel vaisseau ? Décidément, il a de la ressource..."
L26_1 = {}
L26_1.m_CutScenProcessKey = 26
