L27_1 = {}
L27_1.m_CutScenKey_Talk = "NANAHARA_ACT4_INTERLUDE1@27#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 3600403
L27_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L27_1.m_Pos = "C"
L27_1.m_Talk_KOREA = "카토리 가문은 대대로 카미이즈미의 함교를 맡아왔으니까요."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "香取家は代々上泉の指揮を務めてきましたから。"
L27_1.m_Talk_ENG = "The Katori family was traditionally in charge of operating Kamiizumi."
L27_1.m_Talk_TWN = "因爲香取家族世代都負責上泉的艦橋。"
L27_1.m_Talk_THA = "โดยประเพณีแล้วตระกูลคาโทริรับหน้าที่ขับคามิอิสึมิค่ะ"
L27_1.m_Talk_VTN = "gia tộc Katori theo truyền thống là những người chịu trách nhiệm điều hành Kamiizumi."
L27_1.m_Talk_SCN = "香取家族代代都担任上泉舰桥上的要职。"
L27_1.m_Talk_DEU = "Die Familie Katori war ursprünglich für den Betrieb von Kamiizumi verantwortlich."
L27_1.m_Talk_FRA = "De génération en génération, la famille Katori a toujours été chargée du Kamiizumi."
L28_1 = {}
L28_1.m_CutScenKey_Talk = "NANAHARA_ACT4_INTERLUDE1@28#Talk"
L28_1.m_CutScenProcessKey = 28
L28_1.m_CutScenID = 3600403
L28_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L28_1.m_Pos = "C"
L28_1.m_Talk_KOREA = "마사키님 또한, 부친인 에이치 공에게 많은 것을 배웠습니다."
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "雅紀様もまた、御父上の英知様から様々なことを学ばれたと思います。"
L28_1.m_Talk_ENG = "And I’m sure he also learned a lot from his father, Mr. Eichi Katori."
L28_1.m_Talk_TWN = "雅紀也從他父親英知身上學了不少。"
L28_1.m_Talk_THA = "และฉันมั่นใจว่านายท่านมาซากิได้เรียนรู้จากพ่อตัวเองมาเยอะเลยทีเดียว นายท่านเออิจิน่ะค่ะ"
L28_1.m_Talk_VTN = "Và tôi chắc rằng Chủ Nhân Masaki đã học được rất nhiều điều từ cha mình, Ngài Eichi."
L28_1.m_Talk_SCN = "雅纪同样也是，在父亲那里学到了不少知识吧。"
L28_1.m_Talk_DEU = "Und ich bin mir sicher, dass er auch viel von seinem Vater, Eichi Katori, gelernt hat."
L28_1.m_Talk_FRA = "Et puis je suis sûre qu'il a beaucoup appris de son père, Monsieur Eichi Katori."
L29_1 = {}
L29_1.m_CutScenKey_Talk = "NANAHARA_ACT4_INTERLUDE1@29#Talk"
L29_1.m_CutScenProcessKey = 29
L29_1.m_CutScenID = 3600403
L29_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_LAUGH"
L29_1.m_CharStrID = "MINATO_NANA_NULL_NULL"
L29_1.m_Pos = "C"
L29_1.m_Talk_KOREA = "그래? 마사키라면 분명, 함선을 모는 건 멋이 없다면서 거부했을 텐데 말이지."
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "そう？　雅紀のことだからきっと、\n艦船の操縦は地味とか言って拒否したんだと思ったけど。"
L29_1.m_Talk_ENG = "Oh? Masaki would have refused to drive a ship, saying that it’s not cool at all."
L29_1.m_Talk_TWN = "是嗎？我認識雅紀，應該會因為開艦船不帥而拒絕吧？"
L29_1.m_Talk_THA = "โอ๋? มาซากิต้องเคยไม่ยอมขับยานแน่ๆ เจ้าตัวคงว่ามันไม่เท่สักนิด"
L30_1 = "Ồ? Masaki muốn từ chối lái tàu. Cậu ta nói rằng điều đó chẳng hay ho chút nào."
L29_1.m_Talk_VTN = L30_1
L30_1 = "是吗？以雅纪的性格，一定会说驾驶舰船一点都不帅气，然后拒绝学习吧。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Ach was? Masaki hätte sicherlich gesagt, dass es ihm viel zu uncool wäre ein Schiff zu fahren,"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Oh ? Pourtant connaissant Masaki... il aurait jamais trouvé ça « cool », de piloter un vaisseau."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "NANAHARA_ACT4_INTERLUDE1@30#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L30_1.m_CutScenProcessKey = 30
L30_1.m_CutScenID = 3600403
L30_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L30_1.m_Pos = "C"
L31_1 = "가출이라는 명목으로 연합을 떠나 학교를 다니시던 것도 그런 이유였어요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "家出という名目で連合を離れて学校に通っていたのも、\nそのような理由でした。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "That’s why he went to school in the first place, leaving the Alliance behind."
L30_1.m_Talk_ENG = L31_1
L31_1 = "假借離家出走之名，行離開聯盟之實，也是出於這個原因。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เพราะแบบนั้นทีแรกนายท่านมาซากิก็เลยไม่สนใจสมาพันธ์แล้วไปโรงเรียนค่ะ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Đó là lý do tại sao Cậu Masaki đã đến trường ngay từ đầu, bỏ lại Liên Minh."
L30_1.m_Talk_VTN = L31_1
L31_1 = "雅纪离家出走，离开联盟去上学，也是因为这个原因。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "deshalb ist er damals überhaupt zur Schule gegangen und hat die Allianz hinter sich gelassen."
L30_1.m_Talk_DEU = L31_1
L31_1 = "C'est justement pour ça qu'il a choisi de quitter le Clan pour aller à l'école."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "NANAHARA_ACT4_INTERLUDE1@31#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 31
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3600403
L31_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_DESPAIR"
L31_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L31_1.m_Pos = "C"
L32_1 = "3년 전, 에이치 공께서 돌아가신 뒤로는 그분이 돌아오지 않는 이유도 바뀌었지만요."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "3年前、英知様が亡くなられてからは帰ってこない理由も\n変わってしまいましたが。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Then the reason for his leaving changed, when Mr. Eichi Katori passed away three years ago."
L31_1.m_Talk_ENG = L32_1
L32_1 = "不過3年前英知去世後，他不回來的原因也換了。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "แต่แล้วเหตุผลที่เขาจากไปก็เปลี่ยนไป ตอนที่ที่นายท่านเออิจิเสียไปเมื่อสามปีก่อน"
L31_1.m_Talk_THA = L32_1
L32_1 = "Sau đó, lý do rời đi của cậu ấy thay đổi, khi Ngài Eichi qua đời ba năm trước."
L31_1.m_Talk_VTN = L32_1
L32_1 = "不过在3年前，艾奇去世后，他不回来的理由可能就变了吧。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Dann änderte sich der Grund für seine Abwesenheit, als Herr Eichi Katori vor drei Jahren verstarb."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Et puis il y a trois ans, à la mort de son père... il a décidé de ne plus jamais revenir."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
