L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L35_1.m_Pos = "C"
L36_1 = "도착했습니다."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "到着しました。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "We’re here."
L35_1.m_Talk_ENG = L36_1
L36_1 = "我們到了。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ถึงแล้วค่ะ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Chúng ta đến rồi."
L35_1.m_Talk_VTN = L36_1
L36_1 = "到了。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Wir sind da."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Nous sommes arrivés."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "NANAHARA_ACT4_INTERLUDE1@36#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 36
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3600403
L36_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "MINATO_NANA_NULL_NULL"
L36_1.m_Pos = "C"
L37_1 = "정말이야? 제단이라고 하더니. 딱히 뭐가 보이진 않는데?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "本当？　祭壇って聞いてたけど、特に何も見えないな。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Really? I thought there would be an altar here. I don’t see anything."
L36_1.m_Talk_ENG = L37_1
L37_1 = "真的嗎？不是說祭壇嗎？怎麼好像什麼都沒有？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "จริงเหรอ? นึกว่าตรงนี้จะมีแท่นบูชาซะอีก แต่ไม่เห็นมีอะไรเลย"
L36_1.m_Talk_THA = L37_1
L37_1 = "Có thật không? Tôi tưởng là có một đền thờ ở đây. Tôi không thấy gì cả."
L36_1.m_Talk_VTN = L37_1
L37_1 = "真的？不是说有祭坛吗，怎么什么都看不到？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Wirklich? Sollte hier nicht ein Altar sein? Ich sehe überhaupt nichts."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Vraiment ? Mais... il n'y a rien, ici ! Pas même un autel ?"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "NANAHARA_ACT4_INTERLUDE1@37#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3600403
L37_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L37_1.m_Pos = "C"
L38_1 = "……미나토 공."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "……湊様。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Mr. Nayuka."
L37_1.m_Talk_ENG = L38_1
L38_1 = "……南裕夏。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "นายท่านมินาโตะคะ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Cậu Minato."
L37_1.m_Talk_VTN = L38_1
L38_1 = "……峰奈。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Minato."
L37_1.m_Talk_DEU = L38_1
L38_1 = "... Minato."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "NANAHARA_ACT4_INTERLUDE1@38#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 38
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3600403
L38_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L38_1.m_Pos = "C"
L39_1 = "마음이 가볍지는 않겠지만, 한 가지 부탁을 드려도 될까요?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "心苦しい話で恐縮ですが、一つお願いしてもよろしいでしょうか？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "I know this won’t be easy, but may I ask you a favor?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "雖然你會有點沈重，但我可以拜託你一件事嗎？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ฉันรู้ว่านี่คงไม่ง่าย แต่ช่วยอะไรฉันหน่อยได้มั้ยคะ?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Tôi biết điều này sẽ không dễ dàng, nhưng tôi có thể nhờ cậu một việc được không?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "虽然你的心情会很难受，但我能拜托你一件事吗？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Ich weiß, dass wird nicht einfach, aber darf ich dich um einen Gefallen bitten?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Je sais que ça ne va pas être facile, mais... pouvez-vous faire quelque chose pour moi ?"
L38_1.m_Talk_FRA = L39_1
