L47_1 = "치후유에게 들었어."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "千冬から聞いたよ。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "I heard the story from Chifuyu."
L46_1.m_Talk_ENG = L47_1
L47_1 = "千冬有跟我說。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ชิฟุยุเล่าให้ผมฟังแล้วนะ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Tôi đã nghe câu chuyện từ Chifuyu."
L46_1.m_Talk_VTN = L47_1
L47_1 = "我已经听千冬说了。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Ich habe alles bereits von Chifuyu erklärt bekommen."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Chifuyu m'a tout expliqué."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "NANAHARA_ACT4_INTERLUDE1@47#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 47
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3600403
L47_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_CharStrID = "MINATO_NANA_NULL_NULL"
L47_1.m_Pos = "L"
L48_1 = "네 가문의 희생이 있으면, 오로치의 봉인을 지킬 수 있다고."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "七原家の犠牲があれば、オロチの封印を維持することができるって。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "That your sacrifice is required to recover the seal of Orochi."
L47_1.m_Talk_ENG = L48_1
L48_1 = "只要犧牲你們家族，就可以守住大蛇的封印。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ว่าต้องสละชีวิตเธอถึงจะฟื้นฟูผนึกโอโรจิได้น่ะ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Rằng sự hy sinh của cô là cần thiết để phục hồi phong ấn của Orochi."
L47_1.m_Talk_VTN = L48_1
L48_1 = "需要你们家族的人牺牲，才能保住大蛇的封印。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Dass dein Opfer erforderlich ist, um das Siegel von Orochi wieder vollständig zu schließen."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Elle m'a dit que tu comptais te sacrifier pour réparer les sceaux."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "NANAHARA_ACT4_INTERLUDE1@48#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 48
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3600403
L48_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_CharStrID = "MINATO_NANA_NULL_NULL"
L48_1.m_Pos = "L"
L49_1 = "나도 몇 번이고 다시 생각해봤어."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "僕だって何度も何度も考えてみたよ。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "And I thought about it over and over again."
L48_1.m_Talk_ENG = L49_1
L49_1 = "我也不斷在想。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ซึ่งผมก็คิดแล้วคิดอีกนะ"
L48_1.m_Talk_THA = L49_1
L49_1 = "Và tôi đã nghĩ đi nghĩ lại về điều đó."
L48_1.m_Talk_VTN = L49_1
L49_1 = "我考虑了很多次。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Und ich habe immer wieder darüber nachgedacht."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Depuis, ça me trotte dans la tête."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "NANAHARA_ACT4_INTERLUDE1@49#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 49
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3600403
L49_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_CharStrID = "MINATO_NANA_NULL_NULL"
L49_1.m_Pos = "L"
L50_1 = "네 희생을 통해서 이 재난을 해결하는 게…"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "君の犠牲でこの災いを解決するのが……"
L49_1.m_Talk_JPN = L50_1
L50_1 = "If it’s really the only way..."
L49_1.m_Talk_ENG = L50_1
L50_1 = "藉由你的犧牲來解決這場災難…"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ว่าทางเดียวที่จะแก้ปัญหานี้ได้..."
L49_1.m_Talk_THA = L50_1
L50_1 = "Nếu đó thực sự là cách duy nhất..."
L49_1.m_Talk_VTN = L50_1
L50_1 = "通过牺牲你来解决这次的灾难……"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Ob dein Opfer wirklich der einzige Weg ist ..."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Toute cette catastrophe, et ton sacrifice..."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "NANAHARA_ACT4_INTERLUDE1@50#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 50
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3600403
L50_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
