L50_1.m_Face = "UNIT_DESPAIR"
L50_1.m_CharStrID = "MINATO_NANA_NULL_NULL"
L50_1.m_Pos = "L"
L51_1 = "그게 정말로 옳은 것인지를 말이야."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "それが本当に正しいことなのかをね。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "... to solve this problem, with your sacrifice."
L50_1.m_Talk_ENG = L51_1
L51_1 = "真的是對的嗎。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "... มันมีแต่ต้องให้เธอสละชีวิตเองเหรอ"
L50_1.m_Talk_THA = L51_1
L51_1 = "... để giải quyết vấn đề này, với sự hy sinh của cô."
L50_1.m_Talk_VTN = L51_1
L51_1 = "是不是正确的选择。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "... dieses Problem zu lösen."
L50_1.m_Talk_DEU = L51_1
L51_1 = "... n'y a-t-il vraiment pas d'autre solution ?"
L50_1.m_Talk_FRA = L51_1
