L4_1 = "미나토님도 바라셨지요. 평화로운 일상을 돌려받고 싶다고요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "湊様も望んでいらしたはずです。平和な日常を取り戻したいと。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "You also said it yourself. You wanted your peaceful life back."
L3_1.m_Talk_ENG = L4_1
L4_1 = "你也說過，想找回平靜的日常生活。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "คุณก็พูดเองไม่ใช่เหรอคะว่าอยากได้ความสงบสุขกลับคืนมา"
L3_1.m_Talk_THA = L4_1
L4_1 = "Chính cậu cũng đã nói rồi. Cậu muốn cuộc sống yên bình của cậu trở lại."
L3_1.m_Talk_VTN = L4_1
L4_1 = "峰奈不也希望，能重新回归和平的日常吗？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Du hast es doch selbst gesagt! Dass du dein friedliches Leben zurückhaben möchten!"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Vous l'avez dit vous-même, non ? Que vous vouliez retourner à votre vie tranquille."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
