L7_1 = "NANAHARA_ACT4_INTERLUDE1@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 3600403
L6_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "MINATO_NANA_NULL_NULL"
L6_1.m_Pos = "L"
L7_1 = "날 찾아와주고, 날 믿었던 사람이 죽으면, 내 일상이 돌아온다고?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "僕を信じて訪ねてきてくれた人が死んだら、僕の日常が戻ってくるって？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Do you think killing someone who trusted me will bring me peace?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "來找我，而且相信我的人死去後，我的日常生活就會回來？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "เธอคิดว่าการฆ่าคนที่ไว้ใจผมจะทำให้ชีวิตผมสงบสุขเหรอ?"
L6_1.m_Talk_THA = L7_1
L7_1 = "Cô nghĩ rằng giết một người đã đặt niềm tin vào tôi sẽ mang lại cho tôi sự bình yên sao?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "眼睁睁地看着信任我的人死在面前，你认为这样的我还能回归到日常生活吗？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Glaubst du, jemanden zu töten, der an mich geglaubt hat, wird mir Frieden bringen?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Comment pourrais-je te tuer, toi qui m'a accordé ta confiance, et dormir en paix ?"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "NANAHARA_ACT4_INTERLUDE1@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3600403
L7_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "MINATO_NANA_NULL_NULL"
L7_1.m_Pos = "L"
L7_1.m_Crash = 20
L8_1 = "그게 과연, 정말로 내가 바라는 일상일 거라고 생각하는 거야?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "それが本当に僕の望む日常だと思う？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Do you really think that’s the kind of peaceful, ordinary life that I wish for?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "你認為那是我所希望的日常嗎？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "เธอคิดจริงๆ เหรอว่าผมอยากได้ชีวิตสงบสุขธรรมดาๆ พรรค์นั้น"
L7_1.m_Talk_THA = L8_1
L8_1 = "Cô thực sự nghĩ đó là cuộc sống bình thường, yên bình mà tôi mong ước?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "你认为那真的是我希望的日常生活吗？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Glaubst du wirklich, das ist die Art von friedlichem, gewöhnlichem Leben, die ich mir wünsche?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Crois-tu vraiment que c'est ça, le genre de tranquillité à laquelle j'aspire ?"
L7_1.m_Talk_FRA = L8_1
