L10_1 = "이런 결말을 원했던 것은 아닙니다."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "こんな結末を望んでいたわけではありません。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "I don’t want this either."
L9_1.m_Talk_ENG = L10_1
L10_1 = "不想這麼做。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ฉันก็ไม่อยากให้เป็นแบบนี้เหมือนกันค่ะ"
