L11_1 = "NANAHARA_ACT4_INTERLUDE1@60#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 60
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 3600403
L10_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L10_1.m_Pos = "R"
L11_1 = "하지만 충분히 많은 선택을 했고, 또 뒤늦게 너무나도 많은 후회를 해야 했습니다."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "ですが、今まで多くの選択をし、そのあと後悔するということを散々繰り返してきたのです。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "But I already made countless decisions, and they all brought nothing but regret."
L10_1.m_Talk_ENG = L11_1
L11_1 = "但是我已經做過許多選擇，也有許多的後悔。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "แต่ฉันตัดสินใจมานับไม่ถ้วนแล้วนะคะ และก็ไม่ได้อะไรขึ้นมาเลยนอกจากความเสียใจ"
L10_1.m_Talk_THA = L11_1
L11_1 = "Nhưng tôi đã đưa ra vô số quyết định, và tất cả đều không mang lại gì ngoài sự hối tiếc."
L10_1.m_Talk_VTN = L11_1
L11_1 = "但我已经做出了很多错误的选择，因为这些选择，我后悔过很多次。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Doch ich habe bereits unzählige Entscheidungen getroffen, und jede einzelne brachte uns nichts als Bedauern."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Mais par le passé, j'ai fait des choix. Des choix qui n'ont laissé que des regrets."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "NANAHARA_ACT4_INTERLUDE1@61#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 61
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 3600403
L11_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L11_1.m_Pos = "R"
L12_1 = "지금도 현실엔 수많은 사람들이 오로치의 독기에 고통받고 있어요."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "今も多くの人々がオロチの毒によって苦しんでいます。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Even now, so many people are suffering from Orochi’s poison."
L11_1.m_Talk_ENG = L12_1
L12_1 = "直到現在，也還有許多人因為大蛇的毒氣而受苦。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "แม้แต่ตอนนี้ ก็มีคนมากมายต้องทรมานเพราะพิษของโอโรจิ"
L11_1.m_Talk_THA = L12_1
L12_1 = "Ngay cả bây giờ, rất nhiều người đang phải chịu đựng chất độc của Orochi."
L11_1.m_Talk_VTN = L12_1
L12_1 = "现在，还有很多人被大蛇的毒素折磨。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Sogar noch jetzt leiden so viele Menschen an Orochis Gift."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Et à cause de ces choix, le poison d'Orochi fait des ravages aujourd'hui."
L11_1.m_Talk_FRA = L12_1
