L12_1.m_Pos = "R"
L13_1 = "고작 제 한 몸을 희생하는 것뿐입니다."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "ただこの身を犠牲にするだけです。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "All I can do for them is to sacrifice my life."
L12_1.m_Talk_ENG = L13_1
L13_1 = "只要犧牲我一個，"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ที่ฉันทำเพื่อพวกเขาได้ก็มีแต่สละชีวิตตัวเองค่ะ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Tất cả những gì tôi có thể làm cho họ là hy sinh mạng sống của mình."
L12_1.m_Talk_VTN = L13_1
L13_1 = "仅仅需要牺牲我一个人。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Alles, was ich für sie tun kann, ist, mein Leben zu opfern."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Offrir ma vie en sacrifice pour soulager celle des autres, c'est tout ce que je peux faire."
L12_1.m_Talk_FRA = L13_1
