L14_1 = "그걸로 이 비극을 전부 끝맺을 수 있어요."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "それでこの悲劇をすべて終わらせることができます。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Only then, this tragedy will end."
L13_1.m_Talk_ENG = L14_1
L14_1 = "就能結束這場悲劇。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "มีแต่ตอนนั้นเท่านั้น ที่โศกนาฏกรรมนี้จะยุติ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Chỉ có như vậy, bi kịch này mới kết thúc."
L13_1.m_Talk_VTN = L14_1
L14_1 = "就能将悲剧全部终结。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Nur dann kann diese Tragödie enden."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Et alors, enfin, cette tragédie prendra fin."
