L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 3600403
L17_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L17_1.m_Pos = "R"
L18_1 = "저를 통해 모든 이들의 고통을 끝내주세요."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "私の命で皆様の苦しみを終わらせてください。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Help me to end all this suffering."
L17_1.m_Talk_ENG = L18_1
L18_1 = "讓我可以結束所有人的痛苦吧！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ช่วยฉันยุติความทรมานนี้ที"
L17_1.m_Talk_THA = L18_1
L18_1 = "Giúp tôi chấm dứt mọi đau khổ này."
L17_1.m_Talk_VTN = L18_1
L18_1 = "用我来终结他们的痛苦吧。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Hilf mir, all dieses Leiden zu beenden."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Aidez-moi à mettre un terme à toute cette souffrance."
L17_1.m_Talk_FRA = L18_1
