L21_1 = "NANAHARA_ACT4_INTERLUDE1@70#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 70
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 3600403
L20_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_IDLE"
L20_1.m_CharStrID = "MINATO_NANA_NULL_NULL"
L20_1.m_Pos = "C"
L21_1 = "3년 전에 들었던 예견도, 결국 틀렸다고 했었지."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "3年前に聞いた予言も、結局間違っていたと言ったよね。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "The prophecy you had three years ago didn’t go as you wanted."
L20_1.m_Talk_ENG = L21_1
L21_1 = "你不是說過，3年前聽到的預言是個錯誤嗎！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "คำพยากรณ์ที่เธอได้มาเมื่อสามปีก่อนก็ไม่เป็นไปตามที่เธอต้องการ"
L20_1.m_Talk_THA = L21_1
L21_1 = "Lời tiên tri mà cô đưa ra ba năm trước đã không diễn ra như cô muốn."
L20_1.m_Talk_VTN = L21_1
L21_1 = "既然你认为3年前的预言是错误的。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Die Prophezeiung, die vor 3 Jahren hätte erfüllt werden sollen, hatte doch genauso wenig funktioniert!"
L20_1.m_Talk_DEU = L21_1
L21_1 = "La prophétie d'il y a trois ans ne s'est pas réalisée, si ?"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "NANAHARA_ACT4_INTERLUDE1@71#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 71
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 3600403
L21_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "MINATO_NANA_NULL_NULL"
L21_1.m_Pos = "C"
L22_1 = "그렇다면, 이번에도 그렇게 될 수 있어."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "それなら、今回もそうかもしれない。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "It could happen again."
L21_1.m_Talk_ENG = L22_1
L22_1 = "這次也有可能會出錯！"
L21_1.m_Talk_TWN = L22_1
L22_1 = "มันอาจเป็นแบบนั้นอีกก็ได้"
L21_1.m_Talk_THA = L22_1
L22_1 = "Nó có thể xảy ra một lần nữa."
L21_1.m_Talk_VTN = L22_1
L22_1 = "那么，这次难道就不会错了吗？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Genau das könnte wieder passieren."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Et si tu trompais, aujourd'hui aussi ?"
L21_1.m_Talk_FRA = L22_1
