L23_1 = "네……? 그게 무슨."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "はい？　それはどういう……"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Excuse me? I don’t understand..."
L22_1.m_Talk_ENG = L23_1
L23_1 = "嗯……？那是什麼意思？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ยังไงนะคะ? ฉันไม่เข้าใจ..."
L22_1.m_Talk_THA = L23_1
L23_1 = "Xin lỗi? Tôi không hiểu ..."
L22_1.m_Talk_VTN = L23_1
L23_1 = "啊……？什么意思。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Bitte? Was meinst du?"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Pardon ? Je ne vois pas où tu..."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "NANAHARA_ACT4_INTERLUDE1@73#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 73
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3600403
L23_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "MINATO_NANA_NULL_NULL"
L23_1.m_Pos = "C"
L24_1 = "네가 본 미래가, 널 희생해야만 끝나는 미래였다면."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "君が見た未来が、君を犠牲にして終わる未来だったら。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "I mean, if you saw the future where all suffering ends with your sacrifice..."
L23_1.m_Talk_ENG = L24_1
L24_1 = "若你看到的未來，是必須犧牲你才能結束的未來。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "คือ ถ้าเธอเห็นอนาคตที่ความทุกข์ทรมานของทุกคนสิ้นสุดเพะราเธอสละตัวเอง..."
L23_1.m_Talk_THA = L24_1
L24_1 = "Ý tôi là, nếu cô nhìn thấy tương lai nơi mọi đau khổ kết thúc bằng sự hy sinh của cô..."
L23_1.m_Talk_VTN = L24_1
L24_1 = "你看到的未来，如果是只能通过牺牲自我才能获得的未来。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "In der Zukunft, die du vorhergesehen hast, konnte das Leid nur durch dein Opfer beendet werden."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Tu as vu un futur où ton sacrifice mettait fin à toutes les souffrances."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "NANAHARA_ACT4_INTERLUDE1@74#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 74
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3600403
L24_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
