L25_1 = "이번엔 우리가 그걸 바꿀 수도 있지 않을까?"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "今回は僕たちでそれを変えることもできるんじゃないかな？"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Maybe we can change that this time, too."
L24_1.m_Talk_ENG = L25_1
L25_1 = "這次或許我們可以改變結局？"
L24_1.m_Talk_TWN = L25_1
L25_1 = "คราวนี้เราก็อาจเปลี่ยนอนาคตนั้นได้เหมือนกัน..."
L24_1.m_Talk_THA = L25_1
L25_1 = "Có lẽ lần này chúng ta cũng có thể thay đổi điều đó."
L24_1.m_Talk_VTN = L25_1
L25_1 = "那么，我们或许可以改变它？"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Also vielleicht können wir es auch diesmal verändern."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Et si on pouvait le changer, ce futur ?"
L24_1.m_Talk_FRA = L25_1
