L37_1 = "NANAHARA_ACT4_INTERLUDE1@86#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 86
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3600403
L36_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_Face = "UNIT_DESPAIR"
L37_1 = "SAYO_NPC_NANAHARA_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "흐음, 결국 이리로 오게 될 줄 알고 기다렸다만."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "ふむ、ここに来るだろうと思い待っていたが。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Hmpf, I knew you would eventually come here, so I was waiting for you."
L36_1.m_Talk_ENG = L37_1
L37_1 = "嗯，我知道你一定會來這裡，就一直在這等你呢。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "หึ กะแล้วว่าในที่สุดเธอก็ต้องมา ฉันเลยรออยู่"
L36_1.m_Talk_THA = L37_1
L37_1 = "Hừm, ta biết cuối cùng cô sẽ đến đây, vì vậy ta đã đợi cô."
L36_1.m_Talk_VTN = L37_1
L37_1 = "哼，我早料到你也会来这里，所以我一直在等待机会。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "So so ... Genau wie ich es mir vorgestellt habe. Natürlich kommst du hier auch früher oder später vorbeigeschneit."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Hmpf. Te voilà enfin. Je savais que tu finirais par arriver."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "NANAHARA_ACT4_INTERLUDE1@87#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 87
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3600403
L37_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "SAYO_NPC_NANAHARA_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "C"
L38_1 = "정말이지, 또 방해꾼이라니. 지치지도 않는구나."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "まったく、また邪魔者だとは。貴様らも飽きないな。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "But now we have another troublemaker. This is very tiresome."
L37_1.m_Talk_ENG = L38_1
L38_1 = "又一個來搗亂的，不覺得累嗎？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "แต่ตอนนี้เรามีตัวยุ่งมาเพิ่มอีกแล้ว น่าเบื่อหน่ายจริงๆ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Nhưng bây giờ chúng ta có một kẻ gây rối khác. Điều này thật phiền phức."
L37_1.m_Talk_VTN = L38_1
L38_1 = "真是的，碍事的人一个接一个地跑出来，都不知道累的吗？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Achje, das macht ja schon 2 Störenfriede, um die wir uns kümmern müssen ... Wie ermüdend."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Encore un gêneur, hein ? Ça n'en finit pas."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "NANAHARA_ACT4_INTERLUDE1@88#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 88
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3600403
L38_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_Face = "UNIT_SERIOUS"
L39_1 = "SAYO_NPC_NANAHARA_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "C"
L39_1 = "뭐. 네 년이 흘려주는 피라면 언니보단 못하지만, 오로치께서도 별안간 만족하시겠지."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "まあ、貴様が流す血は姉より劣るものではあるが、\nオロチ様も喜んでくださるだろう。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Well, I’m sure Lord Orochi will enjoy your blood regardless, although it does not compare to your sister’s."
L38_1.m_Talk_ENG = L39_1
L39_1 = "反正，雖然你的血不如姊姊，但是從你身上流出來的，大蛇應該還是會滿意吧。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "เอาเถอะ ยังไงฉันก็มั่นใจว่าท่านโอโรจิจะสำราญกับเลือดของพวกเธอ ถึงจะเทียบของพี่เธอไม่ได้ก็เถอะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Chà, ta chắc rằng Chúa Tể Orochi sẽ thích dòng máu của cô, mặc dù nó không thể so sánh với máu của chị cô."
L38_1.m_Talk_VTN = L39_1
L39_1 = "嗯，你流出的血，虽然不如你姐姐的，但大蛇大人也会满足吧。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Nun, ich bin sicher, Orochi wird dein Blut trotzdem genießen, auch wenn es nichts im Gegensatz zu dem deiner Schwester ist."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Enfin, je suis sûre que Seigneur Orochi appréciera ton sang, même s'il n'est pas comparable à celui de ta sœur."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
