L42_1 = "저 사람이…… 장로라고?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "あの人が……長老だって？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "That woman... she’s the elder?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "那個人……是長老？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ผู้หญิงคนนั้น... เธอคือผู้อาวุโสเหรอ?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Người phụ nữ đó... bà ta là trưởng lão ư?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "那家伙……是长老？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Sie ist eine Älteste?"
