L42_1.m_Face = "UNIT_SERIOUS"
L42_1.m_CharStrID = "MINATO_NANA_NULL_NULL"
L42_1.m_Pos = "C"
L43_1 = "그럼 연합을 배신했다는 것도 당신인가요?"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "では、連合を裏切ったのもあなたですか？"
L42_1.m_Talk_JPN = L43_1
L43_1 = "So you’re the one who betrayed the Alliance?"
L42_1.m_Talk_ENG = L43_1
L43_1 = "那背叛聯盟的也是你嗎？"
L42_1.m_Talk_TWN = L43_1
L43_1 = "งั้นคุณก็เป็นคนที่ทรยศสมาพันธ์สินะ?"
L42_1.m_Talk_THA = L43_1
L43_1 = "Vậy ra bà là người đã phản bội Liên Minh?"
L42_1.m_Talk_VTN = L43_1
L43_1 = "那背叛联盟的也是你吗？"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Du bist also diejenige, die die Allianz verraten hat?"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Alors c'est elle qui a trahi le Clan ?"
L42_1.m_Talk_FRA = L43_1
