L47_1 = "SAYO_NPC_NANAHARA_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "C"
L47_1 = "그런 걸 정말로 나 혼자 이뤄냈다고 생각하는 거냐?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "そんなことを本当に私一人で成し遂げたと思っているのか？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Do you think I’m the only one?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "你真的以為憑我一個人辦得到嗎？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "คิดว่ามีแต่ฉันเหรอ?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Cậu tưởng ta là người duy nhất ư?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "你以为这些事都是我一个人做的？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Glaubst du wirklich, ich konnte das alles alleine auf die Beine stellen?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Tu crois peut-être que j'ai fait tout ça toute seule ?"
L46_1.m_Talk_FRA = L47_1
