L47_1.m_Face = "UNIT_LAUGH"
L48_1 = "SAYO_NPC_NANAHARA_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L48_1 = "후훗, 너희들은 모르겠지."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "フフッ、貴様らは知らぬだろう。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Hah hah, you’d never understand."
L47_1.m_Talk_ENG = L48_1
L48_1 = "呵呵，你們都不知道。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ฮ่าฮ่า เขาไม่มีวันเข้าใจหรอก"
L47_1.m_Talk_THA = L48_1
L48_1 = "Ha ha, cô sẽ không bao giờ hiểu được."
L47_1.m_Talk_VTN = L48_1
L48_1 = "呵呵。你们大概不知道吧。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Hahaha, ihr habt ja gar keine Ahnung,"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Hu hu, tu ne pourrais pas comprendre."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "NANAHARA_ACT4_INTERLUDE1@98#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 98
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3600403
L48_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "SAYO_NPC_NANAHARA_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "3년 전에도 너흴 배반했다가 죽어간 녀석들이 얼마나 많은 지 말이다."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "3年前も貴様らを裏切り、死んでいったやつらがどれほど多いのかを。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "There were so many of us who betrayed you and died three years ago."
L48_1.m_Talk_ENG = L49_1
L49_1 = "3年前也有多少傢伙背叛你們後死掉的。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "มีพวกเรามากมายที่ทรยศเธอแล้วตายไปเมื่อสามปีก่อน"
L48_1.m_Talk_THA = L49_1
L49_1 = "Có rất nhiều người trong chúng ta đã phản bội và chết ba năm trước."
L48_1.m_Talk_VTN = L49_1
L49_1 = "在3年前，背叛家族的那些人有多少。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "wie viele von uns sterben mussten, als sie euch das letzte Mal vor 3 Jahre verraten haben ..."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Ils sont nombreux, les traîtres qui se sont sacrifiés il y a trois ans.."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
