L49_1.m_Face = "UNIT_DESPAIR"
L49_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L49_1.m_Pos = "C"
L49_1.m_Crash = 20
L50_1 = "배신자가…… 있었다고요?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "裏切り者が……いたのですか？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "We had betrayers back then?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "有…… 叛徒？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ตอนนั้นเราก็มีคนทรยศเหรอคะ?"
L49_1.m_Talk_THA = L50_1
L50_1 = "Hồi đó chúng ta đã có những kẻ phản bội rồi sao?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "还有……其他背叛者？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Damals gab es auch schon Verräter?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Des traîtres, il y a trois ans ? Que voulez-vous dire ?"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "NANAHARA_ACT4_INTERLUDE1@100#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 100
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3600403
L50_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "SAYO_NPC_NANAHARA_NULL"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "C"
L51_1 = "그렇지. 그날 늙은이들 몇 명에게 내 피를 주고 오로치의 봉인에 뿌리면, 영생을 주겠다고 했어."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "そうだ。あの日、何人かの老いぼれどもに私の血を分け与え、\nそれをオロチ様の封印に捧げられれば永遠の命を与えてやると言ったのだ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Yes. I gave my blood to some of the elderly and told them that they would live forever if they spray my blood on the seal."
L50_1.m_Talk_ENG = L51_1
L51_1 = "沒錯。那天我跟那幾個老頭說，只要把我的血撒在大蛇的封印上，就把永生賜給他們。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "มีสิ ฉันเอาเลือดตัวเองให้ผู้อาวุโสบางคน แล้วก็บอกว่าถ้าพวกเขาพ่นเลือดของฉันลงบนผนึก ก็จะได้มีชีวิตอยู่ไปตลอดกาล"
L50_1.m_Talk_THA = L51_1
L51_1 = "Đúng thế. Ta đã truyền máu của mình cho một số trưởng lão, và nói với họ rằng họ sẽ sống mãi mãi nếu họ phun máu của tôi lên phong ấn."
L50_1.m_Talk_VTN = L51_1
L51_1 = "当然。我把自己的血分给了几个老家伙，和他们说只要洒到大蛇的封印上，就能获得永生。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Ja. Ich gab einigen Ältesten mein Blut und sagte ihnen, dass sie ewig leben würden, wenn sie mein Blut auf das Siegel triefen ließen."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Oui. J'ai donné mon sang à d'autres anciens, en leur promettant la vie éternelle si ils le faisaient sur les sceaux qui retiennent Orochi prisonnier."
L50_1.m_Talk_FRA = L51_1
