L2_1 = "NANAHARA_ACT4_INTERLUDE1@101#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 101
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 3600403
L1_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "SAYO_NPC_NANAHARA_NULL"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "C"
L2_1 = "나처럼 늙지 않는 아름다운 몸으로, 영생을 함께 누릴 수 있을 거라 속삭였을 뿐이란다."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "私のように老いることのない美しい体で、永遠の命を共に享受することができると囁いただけだ。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "I whispered to them that they would stay young forever, like me."
L1_1.m_Talk_ENG = L2_1
L2_1 = "我只是跟他們說可以像我這樣長生不老。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ฉันแอบบอกด้วยว่าพวกเขาจะเยาว์วัยไปตลอดกาลเหมือนฉัน"
L1_1.m_Talk_THA = L2_1
L2_1 = "Tôi thì thầm với họ rằng họ sẽ trẻ mãi không già như ta."
L1_1.m_Talk_VTN = L2_1
L2_1 = "可以像我一样青春永驻，享受永生。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Ich flüsterte ihnen zu, dass sie ewig jung bleiben würden, genau wie ich."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Je leur ai murmuré qu'ils resteraient jeunes toute leur vie, comme moi..."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "NANAHARA_ACT4_INTERLUDE1@102#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 102
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 3600403
L2_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L3_1 = "SAYO_NPC_NANAHARA_NULL"
L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "C"
L3_1 = "녀석들은 망설이지도 않고 앞다퉈서 달려가더구나."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "やつらはためらうこともなく、先を争い走っていったな。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "No one hesitated when they heard my story."
L2_1.m_Talk_ENG = L3_1
L3_1 = "他們就前仆後繼地衝上去。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "พอรู้เรื่องฉันแล้วก็ไม่มีใครลังเลเลย"
L2_1.m_Talk_THA = L3_1
L3_1 = "Không ai do dự khi nghe câu chuyện của ta cả."
L2_1.m_Talk_VTN = L3_1
L3_1 = "那些人可是毫不犹豫，争先恐后地就跑了过去呢。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Niemand zögerte, als sie meine Geschichte hörten."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Alors tu penses bien que quand ils ont entendu mon histoire, il n'ont pas hésité une seconde."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "NANAHARA_ACT4_INTERLUDE1@103#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 103
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 3600403
L3_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "SAYO_NPC_NANAHARA_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L4_1 = "덕분에 난 손가락 하나 까딱하지 않고 봉인을 자극할 수 있었어."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "おかげで私は指一本動かずに封印を刺激することができた。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "It was so easy to disrupt the seal. I didn’t have to do anything."
L3_1.m_Talk_ENG = L4_1
L4_1 = "託他們的福，我連一根手指都不用動，就能夠刺激封印。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "การจะรบกวนผนึกน่ะง่ายมาก ฉันไม่ต้องทำอะไรเลย"
L3_1.m_Talk_THA = L4_1
L4_1 = "Thật dễ dàng để phá vỡ phong ấn. Ta đã không phải làm gì hết."
L3_1.m_Talk_VTN = L4_1
L4_1 = "所以不用我动一根手指，就能刺激到封印，至于那些背叛者是死是活，又与我何关呢？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Es war so einfach, das Siegel zu zerstören. Ich musste praktisch gar nichts tun."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Affaiblir les sceaux n'était qu'un jeu d'enfant. Je n'ai même pas eu à lever le petit doigt."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "NANAHARA_ACT4_INTERLUDE1@104#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 104
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 3600403
L4_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "UNIT_SURPRISE"
L4_1.m_Face = L5_1
L4_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L4_1.m_Pos = "C"
L4_1.m_Crash = 20
L5_1 = "그럴…… 수가."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "そんな……ことが。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "How could it be..."
L4_1.m_Talk_ENG = L5_1
L5_1 = "竟然……"
L4_1.m_Talk_TWN = L5_1
L5_1 = "เป็นไปได้ยังไง..."
L4_1.m_Talk_THA = L5_1
L5_1 = "Sao có thể..."
L4_1.m_Talk_VTN = L5_1
L5_1 = "怎么……会。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Wie kann das sein ..."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Impossible..."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "NANAHARA_ACT4_INTERLUDE1@105#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 3600403
L5_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "UNIT_PRIDE"
L5_1.m_Face = L6_1
L6_1 = "SAYO_NPC_NANAHARA_NULL"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "C"
L6_1 = "선하게 태어나건, 악하게 태어나건, 사람은 오래 살수록 그 추악한 면면이 드러나지."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "善良に生まれようが悪に生まれようが、\n人間は長生きするほどその醜悪な面があらわになる。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Regardless of how they were born, people grow uglier and uglier as their lives go on."
L5_1.m_Talk_ENG = L6_1
L6_1 = "不管是好人或壞人，人活得越久，就越會顯露出醜陋的一面。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ไม่ว่าจะเกิดมายังไง อยู่ๆ ไปคนเรามันก็จะน่ารังเกียจขึ้นเรื่อยๆ นั่นแหละ"
L5_1.m_Talk_THA = L6_1
L6_1 = "Bất kể họ được sinh ra như thế nào, con người ngày càng xấu xí và xấu xí hơn khi cuộc sống của họ tiếp tục."
L5_1.m_Talk_VTN = L6_1
L6_1 = "就算你说人性本善，但只要活得时间越长，人类这种东西就会变得越加丑恶。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Unabhängig davon, wie sie geboren wurden ... Menschen werden im Laufe ihres Lebens immer scheußlicher."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Le cœur des humains s'assombrit avec l'âge. Peu importe à quel point il est pur à la naissance, un esprit finit toujours par être souillé par ses propres désirs."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "NANAHARA_ACT4_INTERLUDE1@106#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 3600403
L6_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_LAUGH"
L7_1 = "SAYO_NPC_NANAHARA_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L7_1 = "그렇게 더럽혀 지기 전에, 너희들의 혼을 오로치님께서 거두어 가시는 것뿐이란다."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "そうやって穢れてしまう前に、貴様らの魂を\nオロチ様にお納めいただくだけだ。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "What Lord Orochi wants is to free your souls while you’re innocent, before you become corrupted."
L6_1.m_Talk_ENG = L7_1
L7_1 = "大蛇只是在你們的靈魂受到污染前，把它拿走而已。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "สิ่งที่ท่านโอโรจิต้องการก็คือปลดปล่อยวิญญาณพวกเจ้าเสียตั้งแต่ที่มันยังบริสุทธิ์อยู่ ก่อนที่มันจะแปดเปื้อนมลทิน"
L6_1.m_Talk_THA = L7_1
L7_1 = "Điều Chúa Tể Orochi muốn là giải phóng linh hồn của cô khi cô còn vô tội, trước khi cô bị ăn mòn, bị tha hóa."
L6_1.m_Talk_VTN = L7_1
L7_1 = "所以，在你们被污染之前，大蛇大人会收取你们的灵魂。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Alles was Orochi verspricht ist, eure Seele zu befreien, bevor ihr verderbt ... Solange ihr noch unschuldig seid."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Mais Seigneur Orochi libérera vos âmes quand elles sont encore pures, avant que vous ne soyez corrompu."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "NANAHARA_ACT4_INTERLUDE1@107#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3600403
L7_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "SAYO_NPC_NANAHARA_NULL"
L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "C"
L8_1 = "이제 그만 그분의 뜻을 받아들이거라."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "そろそろあの方の意志を受け入れよ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Accept her blessings now."
L7_1.m_Talk_ENG = L8_1
L8_1 = "現在就接受她的心意吧。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ทีนี้ก็ยอมรับพรของเธอเสียเถอะ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Hãy chấp nhận lời chúc phúc của Chúa Tể ngay bây giờ."
L7_1.m_Talk_VTN = L8_1
L8_1 = "现在该接受那位大人的意志了。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Nehmt ihren Segen jetzt an."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Soyez sage, et acceptez sa bénédiction."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "NANAHARA_ACT4_INTERLUDE1@108#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 108
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 3600403
L8_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "SAYO_NPC_NANAHARA_NULL"
L8_1.m_CharStrID = L9_1
L8_1.m_Pos = "C"
L9_1 = "그러면 이 땅엔 순수한 영혼들만 남게 될 테니."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "さすれば、この地には純粋な魂だけが残ることになるだろう。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Then only the purest souls will be left on the earth."
L8_1.m_Talk_ENG = L9_1
L9_1 = "這樣這塊土地上就只會留下純真的靈魂。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "แล้วโลกจะได้เหลือแต่วิญญาณบริสุทธิ์"
L8_1.m_Talk_THA = L9_1
L9_1 = "Khi đó chỉ còn lại những linh hồn thuần khiết nhất trên trái đất."
L8_1.m_Talk_VTN = L9_1
L9_1 = "到时候，大地上就会只剩下纯净的灵魂。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Dann werden nur die reinsten Seelen auf der Erde übrigbleiben."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Ainsi, notre monde restera peuplé des âmes les plus pures."
L8_1.m_Talk_FRA = L9_1
