L12_1 = "땅이…… 심장처럼 뛰고 있어."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "地面が……心臓の鼓動みたいに揺れてる。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "The ground... It’s pulsing like a heartbeat."
L11_1.m_Talk_ENG = L12_1
L12_1 = "地……像心臟一樣跳動。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "พื้น... มันสั่นเหมือนหัวใจเต้นเลย"
L11_1.m_Talk_THA = L12_1
L12_1 = "Mặt đất... Nó đang đập như tiếng tim đập."
L11_1.m_Talk_VTN = L12_1
L12_1 = "地面……就像心脏跳动一样。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Der Boden... Er pulsiert wie ein Herz."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Le sol, il tremble... comme un cœur qui bat la chamade."
