L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "C"
L17_1 = "에어버스트 캐논. 타깃에 적중했습니다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "エアーバーストキャノン、ターゲットに命中しました。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Airburst Cannon hit the target."
L16_1.m_Talk_ENG = L17_1
L17_1 = "爆空樂章，命中目標。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ปืนใหญ่กระสุนอากาศโดนเป้าหมาย"
L16_1.m_Talk_THA = L17_1
L17_1 = "Thần Công Nổ Khí bắn trúng mục tiêu."
L16_1.m_Talk_VTN = L17_1
L17_1 = "爆空脉冲。命中目标。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Luftstoß-Kanone: Ziel getroffen."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Canon à explosion d'air. Cible abattue."
L16_1.m_Talk_FRA = L17_1
