L18_1 = "NANAHARA_ACT4_INTERLUDE1@117#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 117
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 3600403
L17_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_LAUGH"
L18_1 = "ZENZIROU_NANA_NULL_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "C"
L18_1 = "이제 몇 마리 안 남았어. 냉각장치 끄고 다시 한번 고도를 높이자고!"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "もう残り数匹だ。冷却装置を止めて、もう一度高度を上げるぞ！"
L17_1.m_Talk_JPN = L18_1
L18_1 = "There aren’t many left now. Turn off the cooling system, and let’s gain some height!"
L17_1.m_Talk_ENG = L18_1
L18_1 = "現在只剩沒幾隻，關掉冷卻裝置，再次提高高度！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "พวกมันเหลือไม่เท่าไหร่แล้ว ปิดระบบทำความเย็นแล้วบินขึ้นเถอะ!"
L17_1.m_Talk_THA = L18_1
L18_1 = "Bây giờ cũng không còn nhiều. Tắt hệ thống làm mát và chúng ta hãy đi lên trên nào!"
L17_1.m_Talk_VTN = L18_1
L18_1 = "只剩下几只灾兽。关闭冷却系统，重新提高高度！"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Jetzt sind nicht mehr viele übrig. Schaltet das Kühlsystem aus und lass uns an Höhe gewinnen!"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Bien, on a fait un sacré ménage. Désactive le système de refroidissement, il est temps de prendre de la hauteur !"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "NANAHARA_ACT4_INTERLUDE1@118#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 118
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 3600403
L18_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "SANAE_NANA_NULL_NULL"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "C"
L19_1 = "……그건 어렵겠군요. 상공으로부터 강한 기상징후를 관측했습니다."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "……それは難しいでしょう。\n上空から強い気象変化の兆候を観測しました。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "We can’t do that. We’re detecting a strong weather anomaly above us."
L18_1.m_Talk_ENG = L19_1
L19_1 = "……有點困難，從上空觀測到強烈的氣象徵兆。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ทำแบบนั้นไม่ได้ค่ะ ตรวจพบอากาศผิดปกติรุนแรงเหนือหัวเรา"
L18_1.m_Talk_THA = L19_1
L19_1 = "Chúng ta không thể làm điều đó. Đã phát hiện thời tiết mạnh bất thường ở phía trên."
L18_1.m_Talk_VTN = L19_1
L19_1 = "……这个有些困难。上空观测到了强大的气流。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Das können wir nicht. Mir werden starke Wetteranomalien auf dem Radar angezeigt!"
L18_1.m_Talk_DEU = L19_1
L19_1 = "... Impossible. Des perturbations météorologiques importantes sont actuellement en train de se produire."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
