L22_1 = "ZENZIROU_NANA_NULL_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "C"
L21_1.m_Crash = 20
L22_1 = "뭐야. 좀 전까지도 멀쩡하던 하늘에 무슨 번개가?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "なんだよ。さっきまで晴れてたのに急に稲妻か？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Lightning? But the sky was clear just a few minutes ago!"
L21_1.m_Talk_ENG = L22_1
L22_1 = "搞什麼？天空剛才明明還好好的，怎麼會突然閃電？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ฟ้าผ่างั้นเหรอ เมื่อกี้ฟ้ายังใสอยู่เลยนะ!"
L21_1.m_Talk_THA = L22_1
L22_1 = "Tia chớp? Nhưng mới vài phút trước bầu trời còn quang đãng!"
L21_1.m_Talk_VTN = L22_1
L22_1 = "搞什么，刚才还是晴朗的天空，怎么突然就打雷了？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Blitze? Bis gerade eben war es doch noch klar?"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Des éclairs ?! Mais le ciel était encore bleu y'a deux minutes !"
L21_1.m_Talk_FRA = L22_1
