L28_1 = "COMMANDER_NPC_NULL_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "R"
L28_1 = "음. 심상치 않은 먹구름이군."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "うむ。ただならぬ暗雲だな。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Hmm, dark clouds are gathering."
L27_1.m_Talk_ENG = L28_1
L28_1 = "嗯，不尋常的烏雲。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "อมมม เมฆดำกำลังรวมตัว"
L27_1.m_Talk_THA = L28_1
L28_1 = "Hmm, những đám mây đen đang tụ tập."
L27_1.m_Talk_VTN = L28_1
L28_1 = "嗯，乌云密布，是很可疑。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Hmm, dunkle Wolken ziehen auf."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Hmm, Ces nuages ne me disent rien qui vaille..."
L27_1.m_Talk_FRA = L28_1
