L30_1 = "COMMANDER_NPC_NULL_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L29_1.m_Crash = 20
L30_1 = "움직여라! 모두 포로들을 데리고 결계 밖으로 대피해야 한다!"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "急げ！　全員、捕虜を連れて結界の外に避難する！"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Everyone, evacuate! We have to get out of this area with the prisoners!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "動作快！帶著所有的俘虜躲到結界外！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ทุกคน อพยพ! เราต้องออกจากพื้นที่นี้พร้อมผู้ต้องขัง!"
L29_1.m_Talk_THA = L30_1
L30_1 = "Mọi người, sơ tán! Chúng ta phải cùng các tù nhân ra khỏi khu vực này!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "都行动起来！大家带着俘虏们离开结界！"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Alle, evakuieren! Wir müssen mit den Gefangenen hier weg!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Tout le monde, évacuez ! Prenez les prisonniers et tirez-vous d'ici !"
L29_1.m_Talk_FRA = L30_1
