L37_1 = "FX_CUTSCEN_HEARTBEAT"
L36_1.m_StartFXSoundName = L37_1
L37_1 = "그것은."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "m_bTalkCenterFadeIn"
L36_1[L37_1] = true
L37_1 = "それは。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Under a dark sky flashing, with lightning..."
L36_1.m_Talk_ENG = L37_1
L37_1 = "那是？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ใต้ท้องฟ้ามืดมิดที่แวบวาบด้วยสายฟ้า..."
L36_1.m_Talk_THA = L37_1
L37_1 = "Dưới bầu trời đen tối nhấp nháy, tia chớp nhập nhoằng..."
L36_1.m_Talk_VTN = L37_1
L37_1 = "那是……"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Unter einem finsteren Himmel, durch Donner und Blitze ..."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Sous un ciel sombre et crépitant..."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "NANAHARA_ACT4_INTERLUDE1@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3600403
L37_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_BGCrash = 40
L38_1 = 0.25
L37_1.m_fBGCrashTime = L38_1
L38_1 = "FX_CUTSCEN_HEARTBEAT"
L37_1.m_StartFXSoundName = L38_1
L38_1 = "비처럼 쏟아지는 벼락과 튀어 오르는 파편의 안개 속에서 유유히 걸어나왔다."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "m_bTalkCenterFadeIn"
L37_1[L38_1] = true
L38_1 = "雨のように降り注ぐ雷と、飛び散る破片の霧の中を悠々と歩いてきた。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "And among the debris and fog covering the ground... It leisurely walked out."
L37_1.m_Talk_ENG = L38_1
L38_1 = "在如雨般不斷落下的閃電，和彈飛的碎片雲霧中，悠哉地走出來。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "และท่ามกลางเศษซากและสายหมอกที่ปกคลุมพื้นดิน... มันปรากฏกายขึ้น ราวทุกสิ่งนั้นล้วนไร้ความหมาย"
L37_1.m_Talk_THA = L38_1
L38_1 = "Và giữa những mảnh vụn và sương mù bao phủ mặt đất... Nó nổi lên, như thể tất cả những điều này chẳng có nghĩa lý gì đối với nó."
L37_1.m_Talk_VTN = L38_1
L38_1 = "一个在如雨般不断落下的闪电和连绵的云雾中闲庭信步的身影。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Zwischen den Trümmern und dem Nebel, der den Boden bedeckt ... Schlich sie hervor."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Du cœur de la brume et des débris célestes... Il est sorti tranquillement."
L37_1.m_Talk_FRA = L38_1
