L39_1.m_fBGCrashTime = L40_1
L40_1 = "FX_CUTSCEN_HEARTBEAT"
L39_1.m_StartFXSoundName = L40_1
L40_1 = "칼처럼 날카롭게. 깃털처럼 가볍게."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "m_bTalkCenterFadeIn"
L39_1[L40_1] = true
L40_1 = "刀のように鋭く。羽根のように軽く。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Sharp as a sword. Light as a feather."
L39_1.m_Talk_ENG = L40_1
L40_1 = "如刀一般鋒利，如羽毛般輕盈。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "คมดุจดาบ เบาดุจขนนก"
L39_1.m_Talk_THA = L40_1
L40_1 = "Sắc bén như gươm, nhẹ tựa lông hồng."
L39_1.m_Talk_VTN = L40_1
L40_1 = "像刀剑一样锋利，像羽毛一样轻盈。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Scharf wie ein Schwert. Leicht wie eine Feder."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Tranchant comme une épée. Léger comme une plume."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
