L41_1 = "FX_CUTSCEN_HEARTBEAT"
L40_1.m_StartFXSoundName = L41_1
L41_1 = "태산처럼 무겁게. 뱀처럼 고요하게."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "m_bTalkCenterFadeIn"
L40_1[L41_1] = true
L41_1 = "山のように重く。蛇のように静かに。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Heavy like a mountain. Silent as a snake."
L40_1.m_Talk_ENG = L41_1
L41_1 = "如泰山般沉重，如蛇一般安靜。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "หนักปานขุนเขา เงียบเบาราวอสรพิษ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Nặng nề như núi, im lặng như rắn."
L40_1.m_Talk_VTN = L41_1
L41_1 = "像泰山一般沉重，又像蛇一样安静。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Schwer wie ein Berg. Leise wie eine Schlange."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Lourd comme une montagne. Silencieux comme un serpent."
L40_1.m_Talk_FRA = L41_1
