L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "우리들의 앞에 나타났다."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "m_bTalkCenterFadeIn"
L42_1[L43_1] = true
L43_1 = "僕たちの前に現れた。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "It stood before us."
L42_1.m_Talk_ENG = L43_1
L43_1 = "就這樣出現在我們眼前。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "มันยืนตระหง่านต่อหน้าเรา"
L42_1.m_Talk_THA = L43_1
L43_1 = "Nó đứng trước mặt chúng ta."
L42_1.m_Talk_VTN = L43_1
L43_1 = "最终，就这样出现在我们面前。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Da stand sie. Direkt vor uns."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Il se tenait devant nous."
L42_1.m_Talk_FRA = L43_1
