L45_1 = "啊啊，终于苏醒了。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Endlich sind Sie erwacht."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Vous êtes enfin réveillé, Maître."
