L46_1 = "UNIT_PRIDE"
L45_1.m_Face = L46_1
L46_1 = "SAYO_NPC_NANAHARA_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "C"
L46_1 = "나나하라 사요, 오로치님의 현신을 뵙나이다."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "七原小夜、オロチ様の現身のお目にかかれて光栄でございます。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "I, Nanahara Sayo, greet the avatar of Orochi."
L45_1.m_Talk_ENG = L46_1
L46_1 = "七原小夜，參見大蛇。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ฉัน นานะฮาระ ซาโยะ ขอทักทายร่างอวตารของโอโรจิ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Tôi, Nanahara Sayo, xin chào mừng sự hiện thân của Orochi."
L45_1.m_Talk_VTN = L46_1
L46_1 = "七原小夜，恭迎大蛇大人降临。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Ich, Nanahara Sayo, grüße den Avatar von Orochi."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Je vous salue, avatar d'Orochi. Nanahara Sayo, pour vous servir..."
L45_1.m_Talk_FRA = L46_1
