L49_1 = "NANAHARA_ACT4_INTERLUDE1@148#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3600403
L48_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "날 깨운 것치고는……"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "私を起こした割には……"
L48_1.m_Talk_JPN = L49_1
L49_1 = "You woke me up..."
L48_1.m_Talk_ENG = L49_1
L49_1 = "叫醒我……"
L48_1.m_Talk_TWN = L49_1
L49_1 = "เจ้าปลุกข้าขึ้นมา..."
L48_1.m_Talk_THA = L49_1
L49_1 = "Ngươi đã đánh thức ta..."
L48_1.m_Talk_VTN = L49_1
L49_1 = "终于，苏醒了……"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Du hast mich erweckt ..."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Pourquoi m'as tu réveillée... ?"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "NANAHARA_ACT4_INTERLUDE1@149#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 149
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3600403
L49_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "인간들의 기세가 팔팔하구나."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "人間どもの勢いは衰えていないようだな。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Yet these humans seem very vigorous."
L49_1.m_Talk_ENG = L50_1
L50_1 = "人類這麼大陣仗嗎？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ทั้งที่เจ้ามนุษย์พวกนี้ก็ยังแข็งแรงกันดีอยู่"
L49_1.m_Talk_THA = L50_1
L50_1 = "Tuy nhiên, những con người này dường như rất mạnh mẽ."
L49_1.m_Talk_VTN = L50_1
L50_1 = "竟然还会有活蹦乱跳的人类出现在我的面前。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Doch diese Menschen scheinen mir noch sehr bei Kraft zu sein ..."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Ces humains-là semblent bien faibles."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "NANAHARA_ACT4_INTERLUDE1@150#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 150
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3600403
L50_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "혹시 혼자의 힘으로는 버거웠던 것이니?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "もしや一人の力では及ばなかったのか？"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Were you not good enough to handle them by yourself?"
L50_1.m_Talk_ENG = L51_1
L51_1 = "還是靠自己一個人的力量太吃力？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "เจ้าไม่สามารถพอจะจัดการพวกมันด้วยตัวเองรึ?"
L50_1.m_Talk_THA = L51_1
L51_1 = "Ngươi không đủ năng lực để tự mình xử lý chúng sao?"
L50_1.m_Talk_VTN = L51_1
L51_1 = "真是废物。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Warst du nicht gut genug, um sie alleine zu erledigen?"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Ne pouvais-tu pas t'en occuper toute seule ?"
L50_1.m_Talk_FRA = L51_1
