L3_1 = "NANAHARA_ACT4_INTERLUDE1@152#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 152
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 3600403
L2_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Face = "UNIT_SERIOUS"
L3_1 = "SAYO_NPC_NANAHARA_NULL"
L2_1.m_CharStrID = L3_1
L3_1 = "그건, 미처 처리하기도 전에 저들이 피를 흘리는 바람에……"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "それが、処理しきる前に彼らが血を流したせいで……"
L2_1.m_Talk_JPN = L3_1
L3_1 = "They spilled the blood before I had the chance to remove them..."
L2_1.m_Talk_ENG = L3_1
L3_1 = "那是，還沒來得及處理，他們就先流血……"
L2_1.m_Talk_TWN = L3_1
L3_1 = "พวกมันหลั่งเลือดมาก่อนที่ฉันจะทันได้กำจัดทิ้งไปค่ะ..."
L2_1.m_Talk_THA = L3_1
L3_1 = "Họ đã đổ máu trước khi tôi có cơ hội loại bỏ chúng..."
L2_1.m_Talk_VTN = L3_1
L3_1 = "对、对不起，在还没来得及处理掉她们之前，就已经流了很多血……"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Das Blut wurde vergossen, bevor ich die Gelegenheit hatte, alle zu vernichten ..."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Celle-ci a versé son sang avant que j'aie le temps d'agir..."
L2_1.m_Talk_FRA = L3_1
