L6_1 = "NANAHARA_ACT4_INTERLUDE1@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 3600403
L5_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "그럼 네 실수로 내가 역겨운 인간들의 냄새를 맡으며 눈을 떴다는 걸까?"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "では、お前の失敗のせいで我は人間どもの悪臭を嗅ぎながら\n目を覚ますことになったということだな？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "So I woke up among these disgusting humans because of your mistake?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "所以是因爲你的失誤，使我聞到人類令人作嘔的氣味後，才睜開眼的嗎？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ข้าก็เลยต้องตื่นมาท่ามกลางมนุษย์น่าขยะแขยงพวกนี้เพราะความผิดพลาดของเจ้ารึ?"
L5_1.m_Talk_THA = L6_1
L6_1 = "Vì vậy, ta thức dậy giữa những con người kinh tởm này bởi vì sai lầm của cô?"
L5_1.m_Talk_VTN = L6_1
L6_1 = "也就是说，因为你的失误，我才会在苏醒的时候，闻到这些恶心的人类的味道？"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Also bin ich gerade etwa wegen deines Fehlers zwischen diesen ekelhaften Menschen erwacht?"
L5_1.m_Talk_DEU = L6_1
L6_1 = "C'est donc à cause de ton incompétence que je suis me suis réveillée au milieu de ces êtres pathétiques"
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
