L21_1.m_fTalkTime = 0.03
L22_1 = "本当にそんな矢で我に当てられるとでも思うたのか？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Do you really believe you can hit me with an arrow like this?"
