L22_1 = "你真的以爲用那種箭能射中我嗎？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "เจ้าคิดว่าจะจู่โจมข้าด้วยธนูพรรค์นี้จริงๆ รึ?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Mi thực sự tin rằng mi có thể bắn trúng ta với một mũi tên như thế này ư?"
