L22_1 = "你以为那种箭矢能伤到我吗？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Glaubst du wirklich, dass du mich mit so einem Pfeil treffen kannst?"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Croyais-tu vraiment pouvoir m'atteindre avec cette misérable flèche ?"
