L28_1 = "무녀의 피가 섞인 것이 둘이라니, 이건 또 별난 구경거리인걸?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "巫女の血が混ざった者が二人もいるとは、これは面白い。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Two with the blood of the priestess. This is particular."
L27_1.m_Talk_ENG = L28_1
L28_1 = "竟然兩個人都參有巫女的血，真是精彩！"
L27_1.m_Talk_TWN = L28_1
L28_1 = "สองคนที่มีเลือดนักบวชหญิง พิเศษทีเดียว"
L27_1.m_Talk_THA = L28_1
L28_1 = "Bằng máu của nữ tư tế. Có chút đặc biệt."
L27_1.m_Talk_VTN = L28_1
L28_1 = "竟然有两个人能够同时拥有巫女之血。真是稀奇。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Gleich zwei mit dem Blut der Priesterin. Wie interessant!"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Deux jumelles qui se partagent le sang de la prêtresse. C'est inattendu."
L27_1.m_Talk_FRA = L28_1
