L35_1 = "나처럼 앞날을 볼 줄 아는구나?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "我のように未来が見えるのだな？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "You can see the future, just like me."
L34_1.m_Talk_ENG = L35_1
L35_1 = "和我一樣看得懂未來？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เจ้ามองเห็นอนาคต เช่นเดียวกับข้า"
L34_1.m_Talk_THA = L35_1
L35_1 = "Ngươi có thể nhìn thấy tương lai, giống như ta."
L34_1.m_Talk_VTN = L35_1
L35_1 = "也能像我一样预见未来吗？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Du kannst wohl auch, wie ich, in die Zukunft sehen ..."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Tu peux voir l'avenir, comme moi."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "NANAHARA_ACT4_INTERLUDE1@185#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 185
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 3600403
L35_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "무녀의 후손 중에서도 그런 피를 타고나는 녀석은 드물 텐데."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "巫女の子孫の中でも、そのような力を持つ者は珍しいはずだが。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "There aren’t many who can see the future, even with the blood of the priestess."
L35_1.m_Talk_ENG = L36_1
L36_1 = "在巫女的後裔中，應該很少有天生就有這種能力的傢伙。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "คนที่เห็นอนาคตได้มีเพียงไม่กี่คน ต่อให้มีเลือดนักบวชหญิงก็ตาม"
L35_1.m_Talk_THA = L36_1
L36_1 = "Không có nhiều người có thể nhìn thấy tương lai, ngay cả với dòng máu của nữ tư tế."
L35_1.m_Talk_VTN = L36_1
L36_1 = "就算是在巫女的后代中，能遗传这种血脉的人也非常稀少。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Es gibt nicht viele, die in die Zukunft sehen können, selbst mit dem Blut der Priesterin."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Même parmi les descendants de la prêtresse, peu sont ceux qui ont hérité de ce don."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "NANAHARA_ACT4_INTERLUDE1@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3600403
L36_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "그래, 지금 네가 보는 미래는 어떻더냐?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "それで、今貴様が見ている未来はどうだ？"
L36_1.m_Talk_JPN = L37_1
L37_1 = "So, what kind of future do you see now?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "那麼，現在你看到的未來如何？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "แล้วตอนนี้เจ้าเห็นอนาคตแบบใดกันล่ะ?"
L36_1.m_Talk_THA = L37_1
L37_1 = "Vậy, giờ đây ngươi nhìn thấy tương lai nào?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "那么，你现在看到的未来是什么样的？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Also ... Welche Zukunft siehst du gerade?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Et dis-moi, quel est le futur que tu vois maintenant ?"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
