L39_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "저런… 모르는 거니?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "おや……知らぬのか？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Oh, do you not know?"
L39_1.m_Talk_ENG = L40_1
L40_1 = "竟然…不知道嗎？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "อ้อ เจ้าไม่รู้งั้นหรือ?"
L39_1.m_Talk_THA = L40_1
L40_1 = "Ồ, ngươi không biết à?"
L39_1.m_Talk_VTN = L40_1
L40_1 = "难道……你不知道？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Ach, hast du etwa keine Ahnung?"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Oh, tu ne vois rien ?"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "NANAHARA_ACT4_INTERLUDE1@190#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 190
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3600403
L40_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "그래."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "そうだな。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "I see."
L40_1.m_Talk_ENG = L41_1
L41_1 = "也是。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เช่นนี้เอง"
L40_1.m_Talk_THA = L41_1
L41_1 = "Ta hiểu rồi."
L40_1.m_Talk_VTN = L41_1
L41_1 = "是啊。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Aha ..."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Intéressant."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "NANAHARA_ACT4_INTERLUDE1@191#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 191
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3600403
L41_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "너에겐, 앞으로 벌어질 일들을 차라리 모르는 게 나을 거다."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "貴様にとって、これから起きることはむしろ知らないほうがいいだろう。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "It would be better for you not to know."
L41_1.m_Talk_ENG = L42_1
L42_1 = "對你來說，不知道以後會發生什麼事或許比較好。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "เจ้าไม่รู้เสียก็น่าจะดีกว่า"
L41_1.m_Talk_THA = L42_1
L42_1 = "Sẽ tốt hơn nếu ngươi không biết."
L41_1.m_Talk_VTN = L42_1
L42_1 = "对你来说，不知道或许会更好。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Wobei ... Vielleicht ist es besser für dich, nicht so genau über die Zukunft Bescheid zu wissen."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Peut-être que ça vaut mieux, après tout."
L41_1.m_Talk_FRA = L42_1
