L46_1.m_fTalkTime = 0.03
L47_1 = "当主様に触れるな！"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Do not touch our Lady!"
L46_1.m_Talk_ENG = L47_1
L47_1 = "不准碰堂主！"
L46_1.m_Talk_TWN = L47_1
L47_1 = "อย่าแตะต้องนายท่านของเรานะ!"
L46_1.m_Talk_THA = L47_1
L47_1 = "Đừng chạm vào Chủ Nhân của chúng ta!"
