L47_1 = "别碰家主！"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Rühren Sie ja nicht unsere Anführerin an!"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Ne touche pas à Dame Nanahara !"
