L49_1 = "너는 보이니? 저 놈의 최후가."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "お前は見えるか？　あやつの最期が。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Do you see the end of this man?"
L48_1.m_Talk_ENG = L49_1
L49_1 = "你看得到嗎？那傢伙的結局？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "เจ้าเห็นจุดจบของชายคนนี้หรือไม่?"
L48_1.m_Talk_THA = L49_1
L49_1 = "Ngươi có thấy cái kết của người đàn ông này không?"
L48_1.m_Talk_VTN = L49_1
L49_1 = "你能看到吗？那个人的结局。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Sieh an? Da sehe ich auch schon das Ende dieses Mannes. Konntest du das auch sehen?"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Et lui ? Vois-tu son avenir ?"
L48_1.m_Talk_FRA = L49_1
