L6_1 = "이럴 수가. 사람이 순식간에……"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "そんな、人があっという間に……"
L5_1.m_Talk_JPN = L6_1
L6_1 = "She killed the man in the blink of an eye..."
L5_1.m_Talk_ENG = L6_1
L6_1 = "怎麼可能，人瞬間……"
L5_1.m_Talk_TWN = L6_1
L6_1 = "เธอฆ่าคนนั้นในพริบตาเดียว..."
L5_1.m_Talk_THA = L6_1
L6_1 = "Bà ta đã giết người đàn ông trong chớp mắt..."
L5_1.m_Talk_VTN = L6_1
