L7_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "그놈의 죽음은 이미 예견된 일이란다."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "あやつの死はすでに予見されたものだ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "His death was destined."
L7_1.m_Talk_ENG = L8_1
L8_1 = "那傢伙的死是預料之中的事。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ความตายของเขาถูกลิขิตไว้แล้ว"
L7_1.m_Talk_THA = L8_1
L8_1 = "Cái chết của anh đã được định sẵn."
L7_1.m_Talk_VTN = L8_1
L8_1 = "他的死亡是早已被预见的事情。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Sein Tod war vorbestimmt."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Sa mort était écrite."
L7_1.m_Talk_FRA = L8_1
