L9_1 = "NANAHARA_ACT4_INTERLUDE1@208#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 208
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 3600403
L8_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "하지만 너희 자매는 그걸 알지 못했겠지."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "しかし貴様ら姉妹はそれを知らなかっただろう。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "But you two didn’t know that."
L8_1.m_Talk_ENG = L9_1
L9_1 = "但是你們姊妹應該沒看出來吧？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "แต่เจ้าสองคนก็ไม่รู้เรื่องนั้น"
L8_1.m_Talk_THA = L9_1
L9_1 = "Nhưng hai người không biết điều đó."
L8_1.m_Talk_VTN = L9_1
L9_1 = "但你们姐妹却并不知道。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Aber ihr beiden wusstet das nicht? Richtig?"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Mais vous ne l'aviez pas vu, n'est-ce pas ?"
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "NANAHARA_ACT4_INTERLUDE1@209#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 209
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 3600403
L9_1.m_CutScenStrID = "NANAHARA_ACT4_INTERLUDE1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "무녀의 이름만 물려받았을 뿐인 평범한 인간들이니 말이다."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "巫女の名を受け継いだだけの、平凡な人間だからな。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "You’re just ordinary humans who inherited nothing but the priestess’s name."
L9_1.m_Talk_ENG = L10_1
L10_1 = "因爲你們是只有繼承巫女名字的平凡人。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "เจ้าเป็นเพียงมนุษย์ธรรมดาที่รับสืบทอดมาเพียงชื่อนักบวชหญิง"
L9_1.m_Talk_THA = L10_1
L10_1 = "Các ngươi chỉ là những con người bình thường không được thừa hưởng gì ngoài cái tên của nữ tư tế."
L9_1.m_Talk_VTN = L10_1
L10_1 = "因为你们虽然继承了巫女之名，却还是平凡的人类。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Ihr seid nur gewöhnliche Menschen, die nichts als den Namen der Priesterin geerbt haben."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Vous deux n'êtes que des êtres ordinaires qui ont simplement hérité du nom de la prêtresse."
L9_1.m_Talk_FRA = L10_1
