L13_1.m_Pos = "C"
L14_1 = "그 몸은 초대 무녀의 것인가요?"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "その体は、初代巫女のものですか？"
L13_1.m_Talk_JPN = L14_1
L14_1 = "That body... It belonged to the first priestess, didn’t it?"
L13_1.m_Talk_ENG = L14_1
L14_1 = "那個身體是初代巫女的嗎？"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ร่างนั่น... เป็นของนักบวชหญิงคนแรกใช่มั้ยคะ?"
L13_1.m_Talk_THA = L14_1
L14_1 = "Cơ thể đó ... Nó thuộc về nữ tư tế đầu tiên, phải không?"
L13_1.m_Talk_VTN = L14_1
L14_1 = "你现在的身体，是初代巫女的吗？"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Dieser Körper... Er gehörte der ersten Priesterin, nicht wahr?"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Ce corps... Il appartenait à la première prêtresse, n'est-ce pas ?"
L13_1.m_Talk_FRA = L14_1
