L17_1 = "NANAHARA_ACT4_INTERLUDE1@216#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 216
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 3600403
