L16_1.m_Pos = "C"
L17_1 = "무녀를 지켜야 할 수호신이…… 그 몸을 취하다니."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "巫女を守るべき守護神が……その身を奪うだなんて。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "You were a guardian god who was supposed to protect the priestess... yet you occupied her body?"
L16_1.m_Talk_ENG = L17_1
L17_1 = "應該要守護巫女的守護神……竟然奪走她的身體。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "คุณเคยเป็นเทพพิทักษ์ที่น่าจะต้องปกป้องนักบวชหญิง... แต่ก็ยังยึดครองร่างของเธอ?"
L16_1.m_Talk_THA = L17_1
L17_1 = "Bà đã từng là thần hộ mệnh, người được cho là bảo vệ nữ tư tế... vậy mà lại chiếm lấy cơ thể của cô ấy?"
L16_1.m_Talk_VTN = L17_1
L17_1 = "本该保护巫女的守护神……会夺取她的身体。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Du warst ein Schutzgott, der die Priesterin beschützen sollte ... Und doch hast du ihren Körper übernommen?"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Cette prêtresse que vous deviez protéger... pourquoi avez-vous pris son corps ?"
L16_1.m_Talk_FRA = L17_1
