L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "C"
L19_1 = "너 같은 녀석의 이해를 바라진 않아."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "貴様ごときに理解など求めておらぬ。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "I don’t need your understanding."
L18_1.m_Talk_ENG = L19_1
L19_1 = "我不奢望你種傢伙能理解。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ข้าไม่จำเป็นต้องให้เจ้าเข้าใจ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Ta không cần ngươi hiểu."
L18_1.m_Talk_VTN = L19_1
L19_1 = "我没期待你这样的人能够理解。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Deine Meinung tangiert mich nicht."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Tu n'as pas besoin de comprendre."
L18_1.m_Talk_FRA = L19_1
