L20_1 = "OROCHI_JAPAN_NULL_NULL"
L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "C"
L20_1 = "넌 그저, 내 원하는 때에 얌전히 죽어주면 될 뿐이란다."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "貴様はただ、我が望む時に大人しく死んでくれればいい。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "All I want from you is to die when I want you to."
L19_1.m_Talk_ENG = L20_1
L20_1 = "你只需要在我需要你去死時，乖乖死去就好。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ข้าต้องการเพียงให้เจ้าตายเสียเมื่อข้าบอกให้ตาย"
L19_1.m_Talk_THA = L20_1
L20_1 = "Tất cả những gì ta muốn là ngươi phải chết khi ta bảo ngươi chết."
L19_1.m_Talk_VTN = L20_1
L20_1 = "你只需要，在我希望的时候乖乖去死就好了。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Alles, was ich von dir will, ist zu sterben, wenn ich es will."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Tout ce que je te demande, c'est de mourir quand je te le dis."
L19_1.m_Talk_FRA = L20_1
